-- Guest Hub — the ads-analysis changes (Ahmed, 27 Nov 2026 — DECISIONS.md 2026-11-27 «Guest Hub: price first, the package
-- question, the unanswered-transfer email»; docs/whatsapp-ads-analysis-2026-11-27.md). GENERATED by
-- scripts/hub-ads-migration.mjs — never edited by hand, never re-run once applied. Every UPDATE / DELETE has a WHERE.
--
--   a. «السعر أولًا» (settings hub_price_first): a room price asked without dates gets «يبدأ من» per room type of the
--      branch — public.hub_from_prices: the lowest OPEN rate of the next N nights (default 30) in the dashboard rate calendar,
--      the website's own rule (room_from_prices, 60 nights) over a shorter window — then the dates with four quick replies.
--   b. the package question (settings hub_package_followup): the engine asks it with buttons right after the package
--      list; an outbound message flagged package_question queues ONE follow-up (public.hub_followups) 3 hours later, sent
--      by hub-agent only inside the 24-hour window, never when the guest wrote anything since, opted out, is blocked or is
--      with the team, never twice for a conversation.
--   c. the unanswered transfer (settings hub_handoff_email, hub_handoff_email_min = 15): a hand-off with no written team
--      reply after N minutes → ONE email to the hub_escalation recipients, else the hub_summary ones (today the morning
--      summary's mailbox, info@armadaresidence.com — no address in a migration) and an alert in «إعدادات المساعد» →
--      «التنبيهات», closed when a staff member replies. No WhatsApp to staff from this path.
-- All three switches start OFF here.

-- internal.hub_setting_keys (20261115400000_guest_hub_media.sql) + the four keys
create or replace function internal.hub_setting_keys() returns text[]
language sql immutable set search_path = '' as $$
  select array['hub_assistant_on', 'hub_inbox_on', 'hub_models', 'hub_model_prices', 'hub_budget_daily_usd', 'hub_budget_monthly_usd',
               'hub_budget_alert_pct', 'hub_confidence_floor', 'hub_burst_ms', 'hub_quote_ttl_min', 'hub_confirm_ttl_min', 'hub_idle_close_hours',
               'hub_human_close_hours', 'hub_cancel_word_wait_hours', 'hub_reply_amber_min', 'hub_reply_red_min', 'hub_escalate_min',
               'hub_failed_understanding_max', 'hub_cards_per_turn', 'hub_reply_max_chars', 'hub_group_min_rooms', 'hub_rate_phone_hour',
               'hub_rate_replies_hour', 'hub_portfolio_limit', 'hub_portfolio_reserve', 'hub_wave_size', 'hub_wave_pause_min',
               'hub_offer_expiry_alert_days', 'hub_card_expiry_alert_days', 'hub_retention_months', 'hub_media_retention_days',
               'hub_spike_factor', 'hub_spike_min', 'hub_summary_time', 'hub_summary_money', 'hub_voice_daily_minutes',
               'hub_price_first', 'hub_package_followup', 'hub_handoff_email', 'hub_handoff_email_min']
$$;


-- internal.hub_setting_check (20261115400000_guest_hub_media.sql) + the four keys
create or replace function internal.hub_setting_check(p_key text, v jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  r integer[] := internal.hub_setting_int_range(p_key);
  n numeric;
  g jsonb;
  e record;
begin
  if r is not null then
    if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric <> floor((v #>> '{}')::numeric)
       or (v #>> '{}')::numeric not between r[1] and r[2] then
      raise exception 'settings.%: a whole number %–%', p_key, r[1], r[2] using errcode = '22023';
    end if;
    return;
  end if;
  case p_key
    when 'hub_assistant_on', 'hub_inbox_on', 'hub_summary_money' then
      if coalesce(jsonb_typeof(v), '') <> 'boolean' then raise exception 'settings.%: true or false', p_key using errcode = '22023'; end if;
      if v = 'true'::jsonb then
        g := internal.hub_switch_gates(p_key);
        if jsonb_array_length(g) > 0 then raise exception 'hub_not_ready' using errcode = 'P0001', detail = g::text; end if;
      end if;
    -- Ahmed, 27 Nov 2026: the three switches of the ads analysis (assistant: edit; no gate) and the email's minutes
    when 'hub_price_first', 'hub_package_followup', 'hub_handoff_email' then
      if coalesce(jsonb_typeof(v), '') <> 'boolean' then raise exception 'settings.%: true or false', p_key using errcode = '22023'; end if;
    when 'hub_handoff_email_min' then
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric <> floor((v #>> '{}')::numeric) or (v #>> '{}')::numeric not between 5 and 240 then
        raise exception 'settings.hub_handoff_email_min: a whole number 5–240' using errcode = '22023';
      end if;
    when 'hub_models' then
      -- H7: transcribe is OpenAI's model id (gpt-…); every other layer is Claude's
      if coalesce(jsonb_typeof(v), '') <> 'object' or not (v ?& array['understand', 'tag', 'translate', 'compose'])
         or exists (select 1 from jsonb_each(v) x where jsonb_typeof(x.value) <> 'string'
                      or x.value #>> '{}' !~ case when x.key = 'transcribe' then '^gpt-[a-z0-9.-]{3,60}$' else '^claude-[a-z0-9.-]{3,60}$' end) then
        raise exception 'settings.hub_models: understand, tag, translate, compose = claude model ids (transcribe: an OpenAI id)' using errcode = '22023';
      end if;
    when 'hub_model_prices' then
      -- [يُؤكَّد] from Anthropic's price page when the engine is built: null until then, else {model: {input, output}} USD / million tokens
      if jsonb_typeof(v) = 'null' then return; end if;
      if coalesce(jsonb_typeof(v), '') <> 'object' then raise exception 'settings.hub_model_prices: null or {model: {input, output}}' using errcode = '22023'; end if;
      for e in select * from jsonb_each(v) loop
        -- H7: OpenAI's transcription model is priced per minute: {per_minute} (USD)
        if e.key ~ '^gpt-[a-z0-9.-]{3,60}$' then
          if coalesce(jsonb_typeof(e.value -> 'per_minute'), '') <> 'number' or (e.value ->> 'per_minute')::numeric not between 0 and 100 then
            raise exception 'settings.hub_model_prices: null or {model: {input, output}} (an OpenAI model: {per_minute})' using errcode = '22023';
          end if;
          continue;
        end if;
        if e.key !~ '^claude-[a-z0-9.-]{3,60}$' or coalesce(jsonb_typeof(e.value -> 'input'), '') <> 'number' or coalesce(jsonb_typeof(e.value -> 'output'), '') <> 'number'
           or (e.value ->> 'input')::numeric not between 0 and 1000 or (e.value ->> 'output')::numeric not between 0 and 1000 then
          raise exception 'settings.hub_model_prices: null or {model: {input, output}}' using errcode = '22023';
        end if;
      end loop;
    when 'hub_budget_daily_usd', 'hub_budget_monthly_usd' then
      -- [يُؤكَّد] Ahmed sets the first trial week's cap before that week: null until then
      if jsonb_typeof(v) = 'null' then return; end if;
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric < 0 or (v #>> '{}')::numeric > 100000 then
        raise exception 'settings.%: null or a number 0–100000 (USD)', p_key using errcode = '22023';
      end if;
    when 'hub_confidence_floor' then
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric not between 0 and 1 then
        raise exception 'settings.hub_confidence_floor: a number 0–1' using errcode = '22023';
      end if;
    when 'hub_spike_factor' then
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric not between 1 and 100 then
        raise exception 'settings.hub_spike_factor: a number 1–100' using errcode = '22023';
      end if;
    when 'hub_summary_time' then
      if coalesce(v #>> '{}', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or jsonb_typeof(v) <> 'string' then
        raise exception 'settings.hub_summary_time: HH:MM' using errcode = '22023';
      end if;
    else
      raise exception 'unknown setting %', p_key using errcode = '22023';
  end case;
end;
$$;


-- ── settings (after their check knows them) ──
insert into public.settings (key, value) values
  ('hub_price_first', 'false'::jsonb), ('hub_package_followup', 'false'::jsonb), ('hub_handoff_email', 'false'::jsonb), ('hub_handoff_email_min', '15'::jsonb)
on conflict (key) do nothing;

-- ── a. «يبدأ من» over the next N nights (service role: hub-agent's adapter) ──
create function public.hub_from_prices(p_branch text, p_days integer default 30)
returns table (room_slug text, from_price numeric)
language sql stable security definer set search_path = '' as $$
  select rt.slug, min(r.price)
    from public.room_types rt
    cross join generate_series(internal.riyadh_today()::timestamp, (internal.riyadh_today() + greatest(1, least(coalesce(p_days, 30), 60)) - 1)::timestamp, interval '1 day') g(d)
    join public.inventory_days i on i.room_type_id = rt.id and i.night = g.d::date and not i.stop_sell and i.rooms_to_sell >= 1
    cross join lateral internal.rate_on(rt.id, g.d::date) r
   where rt.branch = p_branch and rt.active and rt.bookable and rt.on_site and not rt.is_test and r.price is not null
     and internal.site_visible(rt.branch, rt.slug) and internal.branch_switch('show_prices', rt.branch)
   group by rt.slug
$$;
revoke all on function public.hub_from_prices(text, integer) from public, anon, authenticated;
grant execute on function public.hub_from_prices(text, integer) to service_role;

-- ── b. the package follow-up ──
create table public.hub_followups (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.hub_conversations (id) on delete cascade,
  kind text not null check (kind in ('package')),
  question_message_id uuid references public.hub_messages (id) on delete set null,
  due_at timestamptz not null,
  status text not null default 'queued' check (status in ('queued', 'sent', 'skipped')),
  reason text check (reason is null or reason ~ '^[a-z_]{2,40}$'),
  message_id uuid references public.hub_messages (id) on delete set null,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (conversation_id, kind)
);
comment on table public.hub_followups is 'Guest Hub (Ahmed, 27 Nov 2026): ONE follow-up per conversation 3 hours after the package question (hub-agent), inside the 24-hour window only. No text, no phone.';
alter table public.hub_followups enable row level security;
create index hub_followups_due on public.hub_followups (due_at) where status = 'queued';

create function internal.hub_followup_queue() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.direction = 'out' and new.author = 'assistant' and coalesce(new.payload ->> 'package_question', '') = 'true' then
    insert into public.hub_followups (conversation_id, kind, question_message_id, due_at, is_test)
    values (new.conversation_id, 'package', new.id, now() + interval '3 hours', new.is_test)
    on conflict (conversation_id, kind) do nothing;
  end if;
  return null;
end;
$$;
revoke execute on function internal.hub_followup_queue() from public, anon, authenticated;
create trigger hub_messages_followup after insert on public.hub_messages for each row execute function internal.hub_followup_queue();

-- the follow-ups due now (service role, hub-agent): each becomes ONE assistant message with the question's own buttons
create function public.hub_followups_claim(p_text jsonb, p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  f record;
  c public.hub_conversations;
  g public.guest_profiles;
  q public.hub_messages;
  v_lang text;
  v_msg uuid;
  v_ctx jsonb;
  v_out jsonb := '[]'::jsonb;
  v_on boolean := coalesce((select (s.value #>> '{}')::boolean from public.settings s where s.key = 'hub_package_followup'), false);
begin
  for f in select * from public.hub_followups x where x.status = 'queued' and x.due_at <= p_now order by x.due_at limit 20 for update skip locked loop
    select * into c from public.hub_conversations where id = f.conversation_id;
    select * into g from public.guest_profiles where id = c.guest_profile_id;
    select * into q from public.hub_messages where id = f.question_message_id;
    if not v_on then
      update public.hub_followups set status = 'skipped', reason = 'switch_off', updated_at = now() where id = f.id;
    elsif q.id is null then
      update public.hub_followups set status = 'skipped', reason = 'no_question', updated_at = now() where id = f.id;
    elsif exists (select 1 from public.hub_messages m where m.conversation_id = f.conversation_id and m.direction = 'in' and m.created_at > q.created_at) then
      update public.hub_followups set status = 'skipped', reason = 'guest_wrote', updated_at = now() where id = f.id;
    elsif g.wa_opt_out_at is not null or g.hub_blocked_at is not null then
      update public.hub_followups set status = 'skipped', reason = 'opted_out', updated_at = now() where id = f.id;
    elsif c.state in ('human', 'closed') or c.closed_at is not null then
      update public.hub_followups set status = 'skipped', reason = 'with_team', updated_at = now() where id = f.id;
    elsif c.window_expires_at is null or c.window_expires_at <= p_now then
      update public.hub_followups set status = 'skipped', reason = 'window_closed', updated_at = now() where id = f.id;
    else
      begin
        v_ctx := internal.hub_send_context(c);
      exception when others then
        update public.hub_followups set status = 'skipped', reason = 'sending_off', updated_at = now() where id = f.id;
        continue;
      end;
      v_lang := case when c.language = 'en' then 'en' else 'ar' end;
      insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, is_test)
      values (c.id, c.channel_id, 'out', 'assistant', 'interactive', p_text ->> v_lang,
              jsonb_build_object('buttons', q.payload -> 'buttons', 'list_button', q.payload -> 'list_button', 'followup', true), 'fu:' || f.id::text, 'queued', c.is_test)
      returning id into v_msg;
      update public.hub_followups set status = 'sent', message_id = v_msg, updated_at = now() where id = f.id;
      v_out := v_out || jsonb_build_object('send', true, 'context', v_ctx,
        'messages', jsonb_build_array(jsonb_build_object('id', v_msg, 'kind', 'interactive', 'body', p_text ->> v_lang,
                                                         'payload', jsonb_build_object('buttons', q.payload -> 'buttons', 'list_button', q.payload -> 'list_button'))));
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'followups', v_out);
end;
$$;
revoke all on function public.hub_followups_claim(jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.hub_followups_claim(jsonb, timestamptz) to service_role;

-- ── c. the unanswered transfer: the email and the dashboard alert ──
alter table public.booking_notification_recipients drop constraint booking_notification_recipients_scope_check;
alter table public.booking_notification_recipients add constraint booking_notification_recipients_scope_check
  check (scope = any (array['branch', 'partners', 'central', 'careers', 'hub_summary', 'hub_escalation']));
alter table public.booking_notification_recipients drop constraint booking_notification_recipients_hub_filter;
alter table public.booking_notification_recipients add constraint booking_notification_recipients_hub_filter
  check ((scope not in ('hub_summary', 'hub_escalation')) or (not active) or (filter_confirmed_at is not null));

alter table public.hub_alerts drop constraint hub_alerts_kind_check;
alter table public.hub_alerts add constraint hub_alerts_kind_check check (kind = any (array['budget_pct', 'budget_cap', 'portfolio_pct', 'quality_drop',
  'offer_ending', 'card_expiring', 'spike', 'escalation', 'complaint', 'webhook_silent', 'template_rejected', 'api_credit', 'flagged_wrong',
  'model_error', 'voice_cap', 'staff_send', 'departures_missing', 'send_limit', 'booking_request', 'handoff_unanswered']));

alter table public.hub_handoffs add column unanswered_at timestamptz;

-- the transfers waiting past N minutes with no written team reply (service role, hub-agent): ONE email each and an open
-- alert; topics by their Arabic labels, never a guest word or a phone
create function public.hub_handoffs_unanswered_claim(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_on boolean := coalesce((select (s.value #>> '{}')::boolean from public.settings s where s.key = 'hub_handoff_email'), false);
  v_min integer := coalesce((select (s.value #>> '{}')::integer from public.settings s where s.key = 'hub_handoff_email_min'), 15);
  v_to text[];
  r record;
  v_topic text;
  v_out jsonb := '[]'::jsonb;
begin
  if not v_on then return jsonb_build_object('ok', true, 'items', v_out, 'recipients', '[]'::jsonb); end if;
  select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'hub_escalation' and x.active;
  if cardinality(v_to) = 0 then
    select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'hub_summary' and x.active;
  end if;
  for r in select h.id, h.conversation_id, h.unit_id, h.created_at, h.reason, c.topics, coalesce(c.branch_slug, u.branch_slug) as branch, u.kind as unit_kind,
                  u.name_ar as unit_name
             from public.hub_handoffs h join public.hub_conversations c on c.id = h.conversation_id join public.hub_units u on u.id = h.unit_id
            where not h.is_test and not coalesce(h.extra, false) and h.first_reply_at is null and h.closed_at is null and h.unanswered_at is null
              and h.created_at <= p_now - make_interval(mins => v_min) and h.created_at > p_now - interval '2 days'
              and c.state = 'human' and not c.is_test
            order by h.created_at limit 20
            for update of h skip locked loop
    update public.hub_handoffs set unanswered_at = p_now where id = r.id;
    select string_agg(t.label_ar, '، ' order by t.label_ar) into v_topic from public.hub_topics t where t.key = any (coalesce(r.topics, '{}'));
    insert into public.hub_alerts (kind, unit_id, payload)
    values ('handoff_unanswered', r.unit_id, jsonb_build_object('item', r.id::text, 'conversation_id', r.conversation_id, 'branch', r.branch, 'reason', r.reason, 'topic', v_topic))
    on conflict do nothing;
    v_out := v_out || jsonb_build_object('handoff', r.id, 'conversation_id', r.conversation_id, 'short', upper(left(replace(r.conversation_id::text, '-', ''), 8)),
      'branch', r.branch, 'unit_kind', r.unit_kind, 'unit_name', r.unit_name, 'reason', r.reason, 'topic', v_topic,
      'waiting_min', floor(extract(epoch from p_now - r.created_at) / 60)::integer, 'minutes', v_min);
  end loop;
  return jsonb_build_object('ok', true, 'items', v_out, 'recipients', to_jsonb(v_to));
end;
$$;
revoke all on function public.hub_handoffs_unanswered_claim(timestamptz) from public, anon, authenticated;
grant execute on function public.hub_handoffs_unanswered_claim(timestamptz) to service_role;

-- a staff reply (or the hand-off closed) closes its alert
create function internal.hub_handoff_answered() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (new.first_reply_at is not null and old.first_reply_at is null) or (new.closed_at is not null and old.closed_at is null) then
    update public.hub_alerts set acknowledged_at = now()
     where kind = 'handoff_unanswered' and acknowledged_at is null and payload ->> 'item' = new.id::text;
  end if;
  return null;
end;
$$;
revoke execute on function internal.hub_handoff_answered() from public, anon, authenticated;
create trigger hub_handoffs_answered after update of first_reply_at, closed_at on public.hub_handoffs for each row execute function internal.hub_handoff_answered();

-- ── the lab's two «السعر أولًا» items (corrections.json c143, c144) ──
update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": ["ask", "answer"], "must_include": ["يبدأ من"], "must_not_include": ["أقل سعر"]},{"outcome": ["quote", "ask"], "must_include": ["الخميس", "جمادى"], "must_not_include": ["يبدأ من"]}]}'::jsonb
 where key = 'c143' and expect = '{"action": "conversation", "steps": [{"outcome": ["ask", "answer"], "must_not_include": ["يبدأ من", "ابتداء", "أقل سعر", "ريال"]},{"outcome": ["quote", "ask"], "must_include": ["الخميس", "جمادى"], "must_not_include": ["يبدأ من"]}]}'::jsonb;
update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": ["ask", "answer"], "must_include": ["يبدأ من"], "must_not_include": ["أقل سعر"]},{"outcome": "ask", "must_include": ["حسب تواريخ", "armadaresidence.com"], "must_not_include": ["يبدأ من", "ريال"]}]}'::jsonb
 where key = 'c144' and expect = '{"action": "conversation", "steps": [{"outcome": ["ask", "answer"], "must_not_include": ["يبدأ من", "ابتداء", "ريال"]},{"outcome": "ask", "must_include": ["حسب تواريخ", "armadaresidence.com"], "must_not_include": ["يبدأ من", "ريال"]}]}'::jsonb;

-- public.hub_turn_claim (20261125200000_guest_hub_social_lab.sql) + the two switches in its settings
create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  -- H11 (Ahmed, 24 Nov 2026 — «تم، أضفنا ذلك إلى طلبك.» twice in 5 seconds): the turns of one conversation one at a time —
  -- the conversation is locked BEFORE looking for a running turn, so a second claim waits for the first to commit and sees it
  perform 1 from public.hub_conversations where id = t.conversation_id for update;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  -- S1: a brand unit («السوشيال») answers for the conversation's branch once the guest named it (NULL until then)
  if u.kind = 'brand' then u.branch_slug := c.branch_slug; end if;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end,
                              -- «وضع الاستعداد»: no staff reply in the wait — the assistant answers after it
                              standby_outcome = case when standby_until is not null and standby_outcome is null and kind = 'reply'
                                                       and not (v_state = 'closed' or (v_state = 'human' and v_phase is null)) then 'assistant' else standby_outcome end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    -- H10 (bd27baf4 — three cards counted as three replies): the assistant's replies by TURN
    'replies_hour', (select count(distinct m.turn_id) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase, 'human_reason', c.human_reason,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test, 'branch', c.branch_slug, 'branch_pending', c.branch_pending),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled, 'kind', ch.kind, 'provider', ch.provider),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language,
      -- H8: a returning guest's previous room (a confirmed past stay on the same phone) — its card comes first
      'last_room', (select jsonb_build_object('branch', r.branch, 'room', rt.slug) from public.reservations r join public.room_types rt on rt.id = r.room_type_id
                     where r.phone = g.phone and r.status = 'confirmed' and not r.is_test and r.check_out <= internal.riyadh_today() order by r.check_out desc limit 1),
      -- H8: the «إياب» members' prices only for a member with recorded consent (applied by code, never inferred)
      'member', g.club_joined_at is not null and g.consent = 'granted',
      -- H8: «يُعامَل كضيف للتجربة» — a test reservation that never takes a room
      'test_guest', internal.hub_test_guest(g.phone)),
    -- H8: the live «إياب» members' codes of this branch, for a member only
    'member_codes', case when g.club_joined_at is not null and g.consent = 'granted' then
      (select coalesce(jsonb_agg(distinct o.promo_code), '[]'::jsonb) from public.offers o
        where o.audience = 'members' and o.category = 'individuals' and o.live is not null and o.archived_at is null and not o.is_test and o.promo_code is not null
          and (o.valid_to is null or o.valid_to >= internal.riyadh_today()) and (o.branches is null or cardinality(o.branches) = 0 or u.branch_slug is null or u.branch_slug = any (o.branches)))
      else '[]'::jsonb end,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript), 'kind', h.kind, 'at', h.sent_at) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H9: a departure check sent today and not answered yet — a typed answer («بمدد يومين», «طالع الساعة 11») is understood
    -- as «سأغادر في موعدي» / «أرغب في التمديد»; a late check-out question stays an ordinary question
    'departure', (select jsonb_build_object('id', d.id, 'ref', d.nazeel_ref) from public.hub_departures d
                   where d.phone = g.phone and d.branch_slug = u.branch_slug and d.answer is null and d.is_test = c.is_test
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and d.departure_date = internal.riyadh_today()
                   order by d.check_at desc limit 1),
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    -- H10: with the room, the party, breakfast and the recorded cancellation (a reply never contradicts it; the alternatives
    -- of a cancelled stay)
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out,
                                           'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'adults', r.adults, 'children', r.children,
                                           'breakfast', r.breakfast, 'cancel_reason_code', r.cancel_reason_code, 'cancelled_at', r.cancelled_at, 'source', r.booking_source)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and (r.is_test = c.is_test or (r.is_test and internal.hub_test_guest(g.phone)))
                          order by r.created_at desc limit 5) r),
    -- H10: every message we sent this guest outside the chat's text in the last 7 days — the booking templates (rendered by
    -- the engine with the variables they carried), the departure check, the review request, the arrival reminder; no phone
    'sent', (select coalesce(jsonb_agg(s.j order by s.at), '[]') from (
               select w.created_at as at, jsonb_build_object('at', w.created_at, 'template', w.template, 'meta_template', w.meta_template, 'language', w.language,
                        'status', w.status, 'ref', r.ref, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out, 'total', r.total,
                        'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'room_name_ar', r.room_name_ar, 'room_name_en', r.room_name_en,
                        'first_name', split_part(btrim(coalesce(r.guest_name, '')), ' ', 1), 'reason_code', coalesce(w.reason_code, r.cancel_reason_code)) as j
                 from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                where r.phone = g.phone and w.is_test = c.is_test and w.status not in ('failed', 'queued') and w.created_at > now() - interval '7 days'
               union all
               select e.created_at, jsonb_build_object('at', e.created_at, 'template', e.template, 'language', e.language, 'status', e.status)
                 from public.eyab_messages e
                where e.profile_id = g.id and e.is_test = c.is_test and e.status not in ('failed', 'queued') and e.created_at > now() - interval '3 days'
                  and e.template in ('stay_review', 'arrival_reminder', 'eyab_welcome', 'eyab_offer')
               union all
               select d.check_at, jsonb_build_object('at', d.check_at, 'template', 'stay_checkout_check', 'status', d.check_state)
                 from public.hub_departures d
                where d.phone = g.phone and d.is_test = c.is_test and d.check_at is not null and d.check_at > now() - interval '3 days'
                  and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test')
               order by 1 desc limit 8) s),
    -- H10: the hand-off notice ONCE per hand-off episode — whether it already went since the hand-off (no staff reply since),
    -- and whether «ما زال طلبك…» is due (30 minutes since our last message)
    'handoff', case when c.state = 'human' and c.owner_kind is null then jsonb_build_object(
                 'notice_open', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                          and m.created_at >= c.state_changed_at and m.status not in ('failed', 'rejected', 'superseded')
                                          and (coalesce((m.payload ->> 'notice')::boolean, false) or coalesce((m.payload ->> 'handoff')::boolean, false))),
                 'waiting_line_due', coalesce((select max(m.created_at) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                                and m.status not in ('failed', 'rejected', 'superseded')), c.state_changed_at) <= now() - interval '30 minutes')
               end,
    -- H10 (5fb7aac4): a staff or phone message of the last 3 hours asked about leaving or extending («خروج ولا تمديد؟»)
    'staff_departure_q', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.author in ('staff', 'phone')
                                   and m.created_at > now() - interval '3 hours' and coalesce(m.body, '') ~* '(خروج|تمديد|مغادر|تطلع|تغادر|تمدد|check ?out|extend|leaving)'),
    -- S1b: every unit by its OWN licences («التراخيص»; «السوشيال» starts «بموافقة الفريق» — the system admin sets them)
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                           else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'show_prices'), false),
      -- H8: the branch's «الحجز الفوري» (off keeps the booking link as the fallback) and the instant limits (the reason texts)
      'instant_booking', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                               else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'instant_booking'), false),
      'limits', coalesce(internal.setting('instant_limits'), '{"same_day_cutoff": "20:00", "max_nights": 30}'::jsonb),
      -- Ahmed, 27 Nov 2026: «السعر أولًا» and the package question (the switches of «المفاتيح العامة»)
      'price_first', coalesce((select (s.value #>> '{}')::boolean from public.settings s where s.key = 'hub_price_first'), false),
      'package_followup', coalesce((select (s.value #>> '{}')::boolean from public.settings s where s.key = 'hub_package_followup'), false)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

